DELIMITER //

CREATE OR REPLACE PROCEDURE `bag_wear`(IN p_item_id INT, IN p_char_id INT)
BEGIN
  DECLARE v_worn INT DEFAULT 0;
  DECLARE v_rows INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT COUNT(*) INTO v_worn FROM items WHERE holder_char_id = p_char_id AND holder_kind = 'bag' FOR UPDATE;
  IF v_worn > 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'BAG_SLOT_USED' AS code, NULL AS payload;
  ELSE
    UPDATE items SET holder_kind = 'bag' WHERE id = p_item_id AND holder_char_id = p_char_id AND holder_kind = 'held';
    SET v_rows = ROW_COUNT();
    IF v_rows = 0 THEN
      ROLLBACK;
      SELECT 0 AS ok, 'NOT_HELD' AS code, NULL AS payload;
    ELSE
      COMMIT;
      SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('item_id', CAST(p_item_id AS SIGNED)) AS payload;
    END IF;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `campfire_burn_out`(IN p_cooker_id INT, IN p_log_uname VARCHAR(32), IN p_spots JSON)
BEGIN
  -- #95: a campfire went out (burnt: Burnt Logs; rained out at once: Wood Logs): it becomes one log per spot
  -- (p_spots = [{x, y, z, rz}]) in its interior and dimension
  DECLARE v_int TINYINT DEFAULT NULL;
  DECLARE v_dim INT DEFAULT NULL;
  DECLARE v_rows INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT interior, dimension INTO v_int, v_dim FROM items
    WHERE id = p_cooker_id AND type_uname = 'Campfire' AND x IS NOT NULL FOR UPDATE;
  DELETE FROM items WHERE id = p_cooker_id AND type_uname = 'Campfire' AND x IS NOT NULL;
  SET v_rows = ROW_COUNT();
  IF v_rows = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_IN_WORLD' AS code, NULL AS payload;
  ELSE
    INSERT INTO items (type_uname, x, y, z, rz, interior, dimension)
      SELECT p_log_uname, j.x, j.y, j.z, j.rz, v_int, v_dim
      FROM JSON_TABLE(p_spots, '$[*]' COLUMNS (x FLOAT PATH '$.x', y FLOAT PATH '$.y', z FLOAT PATH '$.z',
        rz FLOAT PATH '$.rz')) j;
    SET v_rows = ROW_COUNT();
    COMMIT;
    SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('logs', CAST(v_rows AS SIGNED)) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `character_create`(
  IN p_account_id INT, IN p_skin SMALLINT, IN p_x FLOAT, IN p_y FLOAT, IN p_z FLOAT, IN p_rz FLOAT,
  IN p_hp FLOAT, IN p_food FLOAT, IN p_bleed FLOAT)
BEGIN
  DECLARE v_char INT;
  DECLARE v_cont INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  UPDATE characters SET alive = 0, died_at = IFNULL(died_at, NOW()) WHERE account_id = p_account_id AND alive = 1;
  INSERT INTO characters (account_id, skin, hp, food, bleed, x, y, z, rz)
    VALUES (p_account_id, p_skin, p_hp, p_food, p_bleed, p_x, p_y, p_z, p_rz);
  SET v_char = LAST_INSERT_ID();
  INSERT INTO containers (kind, size, owner_char_id) VALUES ('inventory', 6, v_char);
  SET v_cont = LAST_INSERT_ID();
  UPDATE characters SET inventory_container_id = v_cont WHERE id = v_char;
  COMMIT;
  SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('character_id', CAST(v_char AS SIGNED), 'inventory_container_id', CAST(v_cont AS SIGNED)) AS payload;
END//

CREATE OR REPLACE PROCEDURE `character_death_drop`(IN p_char_id INT, IN p_x FLOAT, IN p_y FLOAT, IN p_z FLOAT,
  IN p_interior TINYINT, IN p_dimension INT, IN p_ring LONGTEXT, IN p_clothes LONGTEXT)
BEGIN
  DECLARE v_n INT DEFAULT 0;
  DECLARE v_inv INT DEFAULT NULL;
  DECLARE v_skin SMALLINT DEFAULT NULL;
  DECLARE v_clothes INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT inventory_container_id, skin INTO v_inv, v_skin FROM characters WHERE id = p_char_id FOR UPDATE;
  CALL character_drop_items(p_char_id, v_inv, p_ring, p_interior, p_dimension, v_n);
  -- upstream death.pwn: the body leaves a Clothes item holding its skin, 1 m along sin/cos(90); p_clothes is that
  -- spot as one ring entry (MTA toJSON of [x, y, z, nx, ny]), at a random heading like the rest
  IF v_skin IS NOT NULL THEN
    INSERT INTO items (type_uname, data, x, y, z, rz, ground_nx, ground_ny, interior, dimension)
      VALUES ('Clothes', JSON_OBJECT('skin', CAST(v_skin AS SIGNED)), JSON_VALUE(p_clothes, '$[0][0]'),
        JSON_VALUE(p_clothes, '$[0][1]'), JSON_VALUE(p_clothes, '$[0][2]'), RAND() * 360,
        JSON_VALUE(p_clothes, '$[0][3]'), JSON_VALUE(p_clothes, '$[0][4]'), p_interior, p_dimension);
    SET v_clothes = LAST_INSERT_ID();
  END IF;
  UPDATE characters SET alive = 0, died_at = NOW(), x = p_x, y = p_y, z = p_z WHERE id = p_char_id;
  COMMIT;
  SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('dropped', CAST(v_n AS SIGNED), 'clothes_item_id', CAST(v_clothes AS SIGNED)) AS payload;
END//

CREATE OR REPLACE PROCEDURE `character_drop_all`(IN p_char_id INT, IN p_ring LONGTEXT, IN p_interior TINYINT,
  IN p_dimension INT)
BEGIN
  -- /dropall (upstream commands.pwn DropItems(death = false)): the death drop without dying, no Clothes item.
  DECLARE v_n INT DEFAULT 0;
  DECLARE v_inv INT DEFAULT NULL;
  DECLARE v_alive TINYINT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT inventory_container_id, alive INTO v_inv, v_alive FROM characters WHERE id = p_char_id FOR UPDATE;
  IF v_alive IS NULL OR v_alive = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_ALIVE' AS code, NULL AS payload;
  ELSE
    CALL character_drop_items(p_char_id, v_inv, p_ring, p_interior, p_dimension, v_n);
    COMMIT;
    SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('dropped', CAST(v_n AS SIGNED)) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `character_drop_items`(IN p_char_id INT, IN p_inv INT, IN p_ring LONGTEXT,
  IN p_interior TINYINT, IN p_dimension INT, OUT p_n INT)
BEGIN
  -- Puts everything the character holds or wears, and its inventory, on the ground (a bag keeps its contents):
  -- item n goes to spot n mod the ring's length, turned to a random heading. p_ring is MTA's toJSON of
  -- [[x, y, z, nx, ny], ...] from character drop.lua: z and the ground normal (nx, ny; 0, 0 = flat) measured by the
  -- client. toJSON's outer [ ] is why the paths start at '$[0]'.
  -- Runs inside the caller's transaction: character_death_drop, character_drop_all.
  DECLARE v_done INT DEFAULT 0;
  DECLARE v_id INT;
  DECLARE v_slot VARCHAR(16);
  DECLARE v_len INT DEFAULT JSON_LENGTH(p_ring, '$[0]');
  DECLARE cur CURSOR FOR
    SELECT id FROM items WHERE holder_char_id = p_char_id OR container_id = p_inv ORDER BY id FOR UPDATE;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
  SET p_n = 0;
  OPEN cur;
  drop_loop: LOOP
    FETCH cur INTO v_id;
    IF v_done = 1 THEN
      LEAVE drop_loop;
    END IF;
    SET v_slot = CONCAT('$[0][', p_n MOD v_len, ']');
    UPDATE items SET holder_char_id = NULL, holder_kind = NULL, container_id = NULL, slot = NULL,
      x = JSON_VALUE(p_ring, CONCAT(v_slot, '[0]')), y = JSON_VALUE(p_ring, CONCAT(v_slot, '[1]')),
      z = JSON_VALUE(p_ring, CONCAT(v_slot, '[2]')), rz = RAND() * 360,
      ground_nx = JSON_VALUE(p_ring, CONCAT(v_slot, '[3]')), ground_ny = JSON_VALUE(p_ring, CONCAT(v_slot, '[4]')),
      interior = p_interior, dimension = p_dimension
      WHERE id = v_id;
    SET p_n = p_n + 1;
  END LOOP;
  CLOSE cur;
END//

CREATE OR REPLACE PROCEDURE `character_flush`(IN p_rows JSON)
BEGIN
  DECLARE v_n INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  UPDATE characters c
    JOIN JSON_TABLE(p_rows, '$[0][*]' COLUMNS (
      id INT PATH '$.id', hp FLOAT PATH '$.hp', food FLOAT PATH '$.food', bleed FLOAT PATH '$.bleed',
      x FLOAT PATH '$.x', y FLOAT PATH '$.y', z FLOAT PATH '$.z', rz FLOAT PATH '$.rz',
      skills LONGTEXT PATH '$.skills', infection INT PATH '$.infection', drugs LONGTEXT PATH '$.drugs')) j ON j.id = c.id
    SET c.hp = j.hp, c.food = j.food, c.bleed = j.bleed, c.x = j.x, c.y = j.y, c.z = j.z, c.rz = j.rz,
      c.skills = COALESCE(j.skills, c.skills), c.infection = COALESCE(j.infection, c.infection),
      c.drugs = COALESCE(j.drugs, c.drugs)
    WHERE c.alive = 1;
  SET v_n = ROW_COUNT();
  COMMIT;
  SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('updated', CAST(v_n AS SIGNED)) AS payload;
END//

CREATE OR REPLACE PROCEDURE `clothes_swap`(IN p_item_id INT, IN p_char_id INT, IN p_new_skin SMALLINT)
BEGIN
  DECLARE v_old SMALLINT DEFAULT NULL;
  DECLARE v_type VARCHAR(32) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT skin INTO v_old FROM characters WHERE id = p_char_id AND alive = 1 FOR UPDATE;
  -- p_char_id IS NOT NULL: with <=> a NULL caller would otherwise match unowned (world) items
  SELECT i.type_uname INTO v_type FROM items i
    LEFT JOIN containers c ON c.id = i.container_id
    LEFT JOIN items owner ON owner.id = c.owner_item_id
    WHERE i.id = p_item_id AND p_char_id IS NOT NULL
      AND (i.holder_char_id <=> p_char_id OR c.owner_char_id <=> p_char_id OR owner.holder_char_id <=> p_char_id)
    FOR UPDATE;
  IF v_old IS NULL THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NO_CHARACTER' AS code, NULL AS payload;
  ELSEIF v_type IS NULL OR v_type <> 'Clothes' THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_OWNED' AS code, NULL AS payload;
  ELSE
    -- upstream OnHoldActionFinish: the item now holds the clothes the character took off
    UPDATE items SET data = JSON_OBJECT('skin', CAST(v_old AS SIGNED)) WHERE id = p_item_id;
    UPDATE characters SET skin = p_new_skin WHERE id = p_char_id;
    COMMIT;
    SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('item_id', CAST(p_item_id AS SIGNED), 'old_skin', CAST(v_old AS SIGNED), 'new_skin', CAST(p_new_skin AS SIGNED)) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `container_put`(IN p_item_id INT, IN p_char_id INT, IN p_container_id INT)
BEGIN
  DECLARE v_owner_char INT DEFAULT NULL;
  DECLARE v_owner_item INT DEFAULT NULL;
  DECLARE v_owner_vehicle INT DEFAULT NULL;
  DECLARE v_owner_holder INT DEFAULT NULL;
  DECLARE v_kind VARCHAR(16) DEFAULT NULL;
  DECLARE v_size INT DEFAULT NULL;
  DECLARE v_used INT DEFAULT 0;
  DECLARE v_item_size INT DEFAULT 1;
  DECLARE v_held INT DEFAULT 0;
  DECLARE v_slot INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT owner_char_id, owner_item_id, owner_vehicle_id, kind, size
    INTO v_owner_char, v_owner_item, v_owner_vehicle, v_kind, v_size
    FROM containers WHERE id = p_container_id FOR UPDATE;
  SELECT COUNT(*) INTO v_held FROM items WHERE id = p_item_id AND holder_char_id = p_char_id AND holder_kind = 'held' FOR UPDATE;
  SELECT t.size INTO v_item_size FROM items i JOIN item_types t ON t.uname = i.type_uname WHERE i.id = p_item_id;
  IF v_owner_item IS NOT NULL THEN
    SELECT holder_char_id INTO v_owner_holder FROM items WHERE id = v_owner_item;
  END IF;
  IF v_size IS NULL OR v_held = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_HELD' AS code, NULL AS payload;
  ELSEIF v_owner_item = p_item_id THEN
    ROLLBACK;
    SELECT 0 AS ok, 'SELF_CONTAINMENT' AS code, NULL AS payload;
  ELSEIF NOT (v_owner_char <=> p_char_id OR v_owner_holder <=> p_char_id OR v_owner_vehicle IS NOT NULL OR v_kind IN ('safebox', 'tent', 'supply')) THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_OWNER' AS code, NULL AS payload;
  ELSE
    SELECT IFNULL(SUM(t.size), 0), IFNULL(MAX(i.slot) + 1, 0) INTO v_used, v_slot
      FROM items i JOIN item_types t ON t.uname = i.type_uname WHERE i.container_id = p_container_id FOR UPDATE;
    IF v_used + v_item_size > v_size THEN
      ROLLBACK;
      SELECT 0 AS ok, 'CONTAINER_FULL' AS code, JSON_OBJECT('used', CAST(v_used AS SIGNED), 'size', CAST(v_size AS SIGNED)) AS payload;
    ELSE
      UPDATE items SET holder_char_id = NULL, holder_kind = NULL, container_id = p_container_id, slot = v_slot WHERE id = p_item_id;
      COMMIT;
      SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('slot', CAST(v_slot AS SIGNED), 'container_id', CAST(p_container_id AS SIGNED)) AS payload;
    END IF;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `container_take`(IN p_item_id INT, IN p_char_id INT)
BEGIN
  DECLARE v_cont INT DEFAULT NULL;
  DECLARE v_slot INT DEFAULT NULL;
  DECLARE v_owner_char INT DEFAULT NULL;
  DECLARE v_owner_item INT DEFAULT NULL;
  DECLARE v_owner_vehicle INT DEFAULT NULL;
  DECLARE v_owner_holder INT DEFAULT NULL;
  DECLARE v_kind VARCHAR(16) DEFAULT NULL;
  DECLARE v_held INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT container_id, slot INTO v_cont, v_slot FROM items WHERE id = p_item_id FOR UPDATE;
  IF v_cont IS NULL THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_IN_CONTAINER' AS code, NULL AS payload;
  ELSE
    SELECT owner_char_id, owner_item_id, owner_vehicle_id, kind
      INTO v_owner_char, v_owner_item, v_owner_vehicle, v_kind
      FROM containers WHERE id = v_cont FOR UPDATE;
    IF v_owner_item IS NOT NULL THEN
      SELECT holder_char_id INTO v_owner_holder FROM items WHERE id = v_owner_item;
    END IF;
    SELECT COUNT(*) INTO v_held FROM items WHERE holder_char_id = p_char_id AND holder_kind = 'held' FOR UPDATE;
    IF NOT (v_owner_char <=> p_char_id OR v_owner_holder <=> p_char_id OR v_owner_vehicle IS NOT NULL OR v_kind IN ('safebox', 'tent', 'supply')) THEN
      ROLLBACK;
      SELECT 0 AS ok, 'NOT_OWNER' AS code, NULL AS payload;
    ELSEIF v_held > 0 THEN
      ROLLBACK;
      SELECT 0 AS ok, 'HANDS_FULL' AS code, NULL AS payload;
    ELSE
      UPDATE items SET container_id = NULL, slot = NULL, holder_char_id = p_char_id, holder_kind = 'held' WHERE id = p_item_id;
      UPDATE items SET slot = slot - 1 WHERE container_id = v_cont AND slot > v_slot ORDER BY slot ASC;
      COMMIT;
      SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('item_id', CAST(p_item_id AS SIGNED), 'container_id', CAST(v_cont AS SIGNED)) AS payload;
    END IF;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `cooker_cook`(IN p_cooker_id INT, IN p_old_data LONGTEXT, IN p_new_data LONGTEXT,
  IN p_food_ids JSON, IN p_near FLOAT)
BEGIN
  -- #95: a cook finished: the cooker's next data (only if unchanged since the read, '' for NULL) and data.cooked = 1
  -- on the listed foods still lying within p_near (x/y) of it
  DECLARE v_rows INT DEFAULT 0;
  DECLARE v_x FLOAT DEFAULT NULL;
  DECLARE v_y FLOAT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT x, y INTO v_x, v_y FROM items WHERE id = p_cooker_id AND x IS NOT NULL FOR UPDATE;
  UPDATE items SET data = p_new_data
    WHERE id = p_cooker_id AND x IS NOT NULL AND IFNULL(data, '') = IFNULL(p_old_data, '');
  SET v_rows = ROW_COUNT();
  IF v_rows = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'BUSY' AS code, NULL AS payload;
  ELSE
    UPDATE items i
      JOIN JSON_TABLE(p_food_ids, '$[*]' COLUMNS (id INT PATH '$')) j ON j.id = i.id
      SET i.data = CASE WHEN JSON_TYPE(i.data) = 'ARRAY' THEN JSON_SET(i.data, '$[0].cooked', 1)
                        ELSE JSON_SET(IFNULL(i.data, '{}'), '$.cooked', 1) END
      WHERE i.x IS NOT NULL AND ABS(i.x - v_x) <= p_near AND ABS(i.y - v_y) <= p_near;
    SET v_rows = ROW_COUNT();
    COMMIT;
    SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('cooked', CAST(v_rows AS SIGNED)) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `cooker_put_food`(IN p_char_id INT, IN p_food_id INT, IN p_cooker_id INT,
  IN p_old_data LONGTEXT, IN p_new_data LONGTEXT, IN p_x FLOAT, IN p_y FLOAT, IN p_z FLOAT, IN p_rz FLOAT)
BEGIN
  -- #95: the held food goes onto a campfire or barbecue; the cooker's data changes only if nobody changed it since
  -- the server read it (p_old_data, '' for NULL)
  DECLARE v_rows INT DEFAULT 0;
  DECLARE v_int TINYINT DEFAULT NULL;
  DECLARE v_dim INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT interior, dimension INTO v_int, v_dim FROM items WHERE id = p_cooker_id AND x IS NOT NULL FOR UPDATE;
  UPDATE items SET data = p_new_data
    WHERE id = p_cooker_id AND x IS NOT NULL AND IFNULL(data, '') = IFNULL(p_old_data, '');
  SET v_rows = ROW_COUNT();
  IF v_rows = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'BUSY' AS code, NULL AS payload;
  ELSE
    UPDATE items SET holder_char_id = NULL, holder_kind = NULL, x = p_x, y = p_y, z = p_z, rz = p_rz,
      interior = v_int, dimension = v_dim
      WHERE id = p_food_id AND holder_char_id = p_char_id AND holder_kind = 'held';
    SET v_rows = ROW_COUNT();
    IF v_rows = 0 THEN
      ROLLBACK;
      SELECT 0 AS ok, 'NOT_HELD' AS code, NULL AS payload;
    ELSE
      COMMIT;
      SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('item_id', CAST(p_food_id AS SIGNED)) AS payload;
    END IF;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `item_create`(
  IN p_type_uname VARCHAR(32), IN p_hitpoints SMALLINT, IN p_data JSON,
  IN p_x FLOAT, IN p_y FLOAT, IN p_z FLOAT, IN p_rz FLOAT, IN p_interior TINYINT, IN p_dimension INT,
  IN p_loot_spawn_id INT, IN p_despawn_at DATETIME)
BEGIN
  DECLARE v_item INT;
  DECLARE v_cont INT DEFAULT NULL;
  DECLARE v_cat VARCHAR(16) DEFAULT NULL;
  DECLARE v_size INT DEFAULT NULL;
  DECLARE v_zone VARCHAR(8) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SELECT category, container_size INTO v_cat, v_size FROM item_types WHERE uname = p_type_uname;
  IF v_cat IS NULL THEN
    SELECT 0 AS ok, 'UNKNOWN_TYPE' AS code, NULL AS payload;
  ELSE
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
    START TRANSACTION;
    IF p_loot_spawn_id IS NOT NULL THEN
      SELECT zone INTO v_zone FROM loot_spawns WHERE id = p_loot_spawn_id;
    END IF;
    INSERT INTO items (type_uname, hitpoints, data, x, y, z, rz, interior, dimension, loot_spawn_id, loot_zone, despawn_at)
      VALUES (p_type_uname, IFNULL(p_hitpoints, 5), p_data, p_x, p_y, p_z, p_rz, p_interior, p_dimension, p_loot_spawn_id, v_zone, p_despawn_at);
    SET v_item = LAST_INSERT_ID();
    IF v_cat IN ('bag', 'safebox') THEN
      INSERT INTO containers (kind, size, owner_item_id) VALUES (v_cat, IFNULL(v_size, 8), v_item);
      SET v_cont = LAST_INSERT_ID();
    END IF;
    COMMIT;
    SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('item_id', CAST(v_item AS SIGNED), 'container_id', CAST(v_cont AS SIGNED)) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `item_create_held`(
  IN p_type_uname VARCHAR(32), IN p_char_id INT)
BEGIN
  DECLARE v_alive INT DEFAULT 0;
  DECLARE v_held INT DEFAULT 0;
  DECLARE v_cat VARCHAR(16) DEFAULT NULL;
  DECLARE v_size INT DEFAULT NULL;
  DECLARE v_item INT DEFAULT 0;
  DECLARE v_cont INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SELECT category, container_size INTO v_cat, v_size FROM item_types WHERE uname = p_type_uname;
  IF v_cat IS NULL THEN
    SELECT 0 AS ok, 'UNKNOWN_TYPE' AS code, NULL AS payload;
  ELSE
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
    START TRANSACTION;
    SELECT COUNT(*) INTO v_alive FROM characters WHERE id = p_char_id AND alive = 1 FOR UPDATE;
    SELECT COUNT(*) INTO v_held FROM items WHERE holder_char_id = p_char_id AND holder_kind = 'held' FOR UPDATE;
    IF v_alive = 0 THEN
      ROLLBACK;
      SELECT 0 AS ok, 'NO_CHARACTER' AS code, NULL AS payload;
    ELSEIF v_held > 0 THEN
      ROLLBACK;
      SELECT 0 AS ok, 'HANDS_FULL' AS code, NULL AS payload;
    ELSE
      INSERT INTO items (type_uname, hitpoints, holder_char_id, holder_kind)
        VALUES (p_type_uname, 5, p_char_id, 'held');
      SET v_item = LAST_INSERT_ID();
      -- a bag or safebox gets its container, as in item_create (a crafted ParaBag had none)
      IF v_cat IN ('bag', 'safebox') THEN
        INSERT INTO containers (kind, size, owner_item_id) VALUES (v_cat, IFNULL(v_size, 8), v_item);
        SET v_cont = LAST_INSERT_ID();
      END IF;
      COMMIT;
      SELECT 1 AS ok, 'OK' AS code,
        JSON_OBJECT('item_id', CAST(v_item AS SIGNED), 'container_id', CAST(v_cont AS SIGNED)) AS payload;
    END IF;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `item_create_in_container`(IN p_type_uname VARCHAR(32), IN p_container_id INT)
BEGIN
  DECLARE v_cat VARCHAR(16) DEFAULT NULL;
  DECLARE v_item_size INT DEFAULT 1;
  DECLARE v_bag_size INT DEFAULT NULL;
  DECLARE v_size INT DEFAULT NULL;
  DECLARE v_used INT DEFAULT 0;
  DECLARE v_slot INT DEFAULT 0;
  DECLARE v_item INT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SELECT category, size, container_size INTO v_cat, v_item_size, v_bag_size
    FROM item_types WHERE uname = p_type_uname;
  IF v_cat IS NULL THEN
    SELECT 0 AS ok, 'UNKNOWN_TYPE' AS code, NULL AS payload;
  ELSE
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
    START TRANSACTION;
    SELECT size INTO v_size FROM containers WHERE id = p_container_id FOR UPDATE;
    IF v_size IS NULL THEN
      ROLLBACK;
      SELECT 0 AS ok, 'NO_CONTAINER' AS code, NULL AS payload;
    ELSE
      SELECT IFNULL(SUM(t.size), 0), IFNULL(MAX(i.slot) + 1, 0) INTO v_used, v_slot
        FROM items i JOIN item_types t ON t.uname = i.type_uname WHERE i.container_id = p_container_id FOR UPDATE;
      IF v_used + v_item_size > v_size THEN
        ROLLBACK;
        SELECT 0 AS ok, 'CONTAINER_FULL' AS code, NULL AS payload;
      ELSE
        INSERT INTO items (type_uname, hitpoints, container_id, slot) VALUES (p_type_uname, 5, p_container_id, v_slot);
        SET v_item = LAST_INSERT_ID();
        IF v_cat IN ('bag', 'safebox') THEN
          INSERT INTO containers (kind, size, owner_item_id) VALUES (v_cat, IFNULL(v_bag_size, 8), v_item);
        END IF;
        COMMIT;
        SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('item_id', CAST(v_item AS SIGNED), 'slot', CAST(v_slot AS SIGNED)) AS payload;
      END IF;
    END IF;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `item_data_flush`(IN p_rows JSON)
BEGIN
  -- p_rows: MTA's toJSON of [{id, data = JSON text}] (wrapped in an outer array): the held items whose data changed
  DECLARE v_n INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  UPDATE items i
    JOIN JSON_TABLE(p_rows, '$[0][*]' COLUMNS (id INT PATH '$.id', data LONGTEXT PATH '$.data')) j ON j.id = i.id
    SET i.data = j.data;
  SET v_n = ROW_COUNT();
  COMMIT;
  SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('updated', CAST(v_n AS SIGNED)) AS payload;
END//

CREATE OR REPLACE PROCEDURE `item_destroy`(IN p_item_id INT, IN p_char_id INT)
BEGIN
  DECLARE v_rows INT DEFAULT 0;
  DECLARE v_cont INT DEFAULT NULL;
  DECLARE v_slot INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT container_id, slot INTO v_cont, v_slot FROM items WHERE id = p_item_id FOR UPDATE;
  -- p_char_id IS NOT NULL: with <=> a NULL caller would otherwise match unowned (world) items
  DELETE i FROM items i
    LEFT JOIN containers c ON c.id = i.container_id
    LEFT JOIN items owner ON owner.id = c.owner_item_id
    WHERE i.id = p_item_id AND p_char_id IS NOT NULL
      AND (i.holder_char_id <=> p_char_id OR c.owner_char_id <=> p_char_id OR owner.holder_char_id <=> p_char_id);
  SET v_rows = ROW_COUNT();
  IF v_rows = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_OWNED' AS code, NULL AS payload;
  ELSE
    IF v_cont IS NOT NULL THEN
      UPDATE items SET slot = slot - 1 WHERE container_id = v_cont AND slot > v_slot ORDER BY slot ASC;
    END IF;
    COMMIT;
    SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('item_id', CAST(p_item_id AS SIGNED)) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `item_disarm`(
  IN p_actor_char_id INT, IN p_target_char_id INT, IN p_item_id INT)
BEGIN
  DECLARE v_actor_alive INT DEFAULT 0;
  DECLARE v_actor_held INT DEFAULT 0;
  DECLARE v_rows INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT COUNT(*) INTO v_actor_alive FROM characters WHERE id = p_actor_char_id AND alive = 1 FOR UPDATE;
  SELECT COUNT(*) INTO v_actor_held FROM items WHERE holder_char_id = p_actor_char_id AND holder_kind = 'held' FOR UPDATE;
  IF v_actor_alive = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NO_CHARACTER' AS code, NULL AS payload;
  ELSEIF v_actor_held > 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'HANDS_FULL' AS code, NULL AS payload;
  ELSE
    UPDATE items SET holder_char_id = p_actor_char_id
      WHERE id = p_item_id AND holder_char_id = p_target_char_id AND holder_kind = 'held';
    SET v_rows = ROW_COUNT();
    IF v_rows = 0 THEN
      ROLLBACK;
      SELECT 0 AS ok, 'NOT_HELD' AS code, NULL AS payload;
    ELSE
      COMMIT;
      SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('item_id', CAST(p_item_id AS SIGNED)) AS payload;
    END IF;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `item_drop`(IN p_item_id INT, IN p_char_id INT, IN p_x FLOAT, IN p_y FLOAT, IN p_z FLOAT,
  IN p_rz FLOAT, IN p_interior TINYINT, IN p_dimension INT)
BEGIN
  DECLARE v_rows INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  UPDATE items SET holder_char_id = NULL, holder_kind = NULL, x = p_x, y = p_y, z = p_z, rz = p_rz,
    interior = p_interior, dimension = p_dimension
    WHERE id = p_item_id AND holder_char_id = p_char_id AND holder_kind = 'held';
  SET v_rows = ROW_COUNT();
  IF v_rows = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_HELD' AS code, NULL AS payload;
  ELSE
    COMMIT;
    SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('item_id', CAST(p_item_id AS SIGNED)) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `item_pickup`(IN p_item_id INT, IN p_char_id INT)
BEGIN
  DECLARE v_alive INT DEFAULT 0;
  DECLARE v_held INT DEFAULT 0;
  DECLARE v_rows INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT COUNT(*) INTO v_alive FROM characters WHERE id = p_char_id AND alive = 1 FOR UPDATE;
  SELECT COUNT(*) INTO v_held FROM items WHERE holder_char_id = p_char_id AND holder_kind = 'held' FOR UPDATE;
  IF v_alive = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NO_CHARACTER' AS code, NULL AS payload;
  ELSEIF v_held > 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'HANDS_FULL' AS code, NULL AS payload;
  ELSE
    UPDATE items SET holder_char_id = p_char_id, holder_kind = 'held', x = NULL, y = NULL, z = NULL, rz = NULL,
      interior = NULL, dimension = NULL, loot_spawn_id = NULL, despawn_at = NULL
      WHERE id = p_item_id AND x IS NOT NULL;
    SET v_rows = ROW_COUNT();
    IF v_rows = 0 THEN
      ROLLBACK;
      SELECT 0 AS ok, 'NOT_IN_WORLD' AS code, NULL AS payload;
    ELSE
      COMMIT;
      SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('item_id', CAST(p_item_id AS SIGNED)) AS payload;
    END IF;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `item_transfer_world`(
  IN p_char_id INT, IN p_held_id INT, IN p_world_id INT,
  IN p_held_data JSON, IN p_world_data JSON,
  IN p_delete_world TINYINT, IN p_delete_held TINYINT)
BEGIN
  DECLARE v_held_ok INT DEFAULT 0;
  DECLARE v_world_ok INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT COUNT(*) INTO v_held_ok FROM items
    WHERE id = p_held_id AND holder_char_id = p_char_id AND holder_kind = 'held' FOR UPDATE;
  SELECT COUNT(*) INTO v_world_ok FROM items
    WHERE id = p_world_id AND x IS NOT NULL FOR UPDATE;
  IF v_held_ok = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_HELD' AS code, NULL AS payload;
  ELSEIF v_world_ok = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_IN_WORLD' AS code, NULL AS payload;
  ELSE
    IF p_delete_held = 1 THEN
      DELETE FROM items WHERE id = p_held_id;
    ELSE
      UPDATE items SET data = p_held_data WHERE id = p_held_id;
    END IF;
    IF p_delete_world = 1 THEN
      DELETE FROM items WHERE id = p_world_id;
    ELSE
      UPDATE items SET data = p_world_data WHERE id = p_world_id;
    END IF;
    COMMIT;
    SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT(
      'held_id', CAST(p_held_id AS SIGNED),
      'world_id', CAST(p_world_id AS SIGNED),
      'deleted_world', CAST(p_delete_world AS SIGNED),
      'deleted_held', CAST(p_delete_held AS SIGNED)
    ) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `item_unwear`(IN p_char_id INT, IN p_holder_kind VARCHAR(16))
BEGIN
  DECLARE v_item_id INT DEFAULT NULL;
  DECLARE v_held INT DEFAULT 0;
  DECLARE v_inv INT DEFAULT NULL;
  DECLARE v_free_slot INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF p_holder_kind NOT IN ('hat', 'mask', 'armour', 'holster', 'bag') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid holder_kind for item_unwear';
  END IF;

  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;

  SELECT id INTO v_item_id
    FROM items WHERE holder_char_id = p_char_id AND holder_kind = p_holder_kind FOR UPDATE;

  IF v_item_id IS NULL THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_WORN' AS code, NULL AS payload;
  ELSE
    SELECT COUNT(*) INTO v_held
      FROM items WHERE holder_char_id = p_char_id AND holder_kind = 'held';

    IF v_held = 0 THEN
      UPDATE items
        SET holder_char_id = p_char_id, holder_kind = 'held', container_id = NULL, slot = NULL
        WHERE id = v_item_id;
      COMMIT;
      SELECT 1 AS ok, 'OK' AS code,
        JSON_OBJECT(
          'item_id', CAST(v_item_id AS SIGNED),
          'destination', 'held',
          'slot', p_holder_kind
        ) AS payload;
    ELSE
      SELECT inventory_container_id INTO v_inv FROM characters WHERE id = p_char_id;

      SELECT s.n INTO v_free_slot
      FROM (SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5) s
      WHERE s.n NOT IN (SELECT slot FROM items WHERE container_id = v_inv AND slot IS NOT NULL)
      ORDER BY s.n LIMIT 1;

      IF v_free_slot IS NOT NULL THEN
        UPDATE items
          SET holder_char_id = NULL, holder_kind = NULL, container_id = v_inv, slot = v_free_slot
          WHERE id = v_item_id;
        COMMIT;
        SELECT 1 AS ok, 'OK' AS code,
          JSON_OBJECT(
            'item_id', CAST(v_item_id AS SIGNED),
            'destination', 'inventory',
            'slot', CAST(v_free_slot AS SIGNED),
            'wear_slot', p_holder_kind
          ) AS payload;
      ELSE
        ROLLBACK;
        SELECT 0 AS ok, 'INVENTORY_FULL' AS code, NULL AS payload;
      END IF;
    END IF;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `item_wear`(IN p_item_id INT, IN p_char_id INT, IN p_holder_kind VARCHAR(16))
BEGIN
  DECLARE v_item_char INT DEFAULT NULL;
  DECLARE v_item_kind VARCHAR(16) DEFAULT NULL;
  DECLARE v_item_container INT DEFAULT NULL;
  DECLARE v_item_slot INT DEFAULT NULL;
  DECLARE v_old_id INT DEFAULT NULL;
  DECLARE v_cont_owner INT DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF p_holder_kind NOT IN ('hat', 'mask', 'armour', 'holster', 'bag') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid holder_kind for item_wear';
  END IF;

  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;

  SELECT holder_char_id, holder_kind, container_id, slot
    INTO v_item_char, v_item_kind, v_item_container, v_item_slot
    FROM items WHERE id = p_item_id FOR UPDATE;

  IF v_item_char <=> p_char_id THEN
    SET v_cont_owner = p_char_id;
  ELSEIF v_item_container IS NOT NULL THEN
    SELECT owner_char_id INTO v_cont_owner FROM containers WHERE id = v_item_container;
  END IF;

  IF NOT (v_cont_owner <=> p_char_id) THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_OWNER' AS code, NULL AS payload;
  ELSE
    SELECT id INTO v_old_id
      FROM items WHERE holder_char_id = p_char_id AND holder_kind = p_holder_kind FOR UPDATE;

    IF v_old_id IS NOT NULL THEN
      -- Temporarily clear holder_kind to prevent duplicate key collision during swap
      UPDATE items SET holder_kind = NULL WHERE id = v_old_id;
    END IF;

    UPDATE items
      SET holder_char_id = p_char_id, holder_kind = p_holder_kind, container_id = NULL, slot = NULL
      WHERE id = p_item_id;

    IF v_old_id IS NOT NULL THEN
      IF v_item_kind = 'held' THEN
        UPDATE items SET holder_char_id = p_char_id, holder_kind = 'held', container_id = NULL, slot = NULL WHERE id = v_old_id;
      ELSEIF v_item_container IS NOT NULL THEN
        UPDATE items SET holder_char_id = NULL, holder_kind = NULL, container_id = v_item_container, slot = v_item_slot WHERE id = v_old_id;
      ELSE
        UPDATE items SET holder_char_id = p_char_id, holder_kind = 'held', container_id = NULL, slot = NULL WHERE id = v_old_id;
      END IF;
    END IF;

    COMMIT;
    SELECT 1 AS ok, 'OK' AS code,
      JSON_OBJECT(
        'item_id', CAST(p_item_id AS SIGNED),
        'swapped_id', CAST(v_old_id AS SIGNED),
        'slot', p_holder_kind
      ) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `loot_roll`(IN p_rolls JSON, IN p_despawn_minutes INT)
BEGIN
  -- p_rolls: MTA's toJSON of [{s = spawn id, cd = cooldown seconds, items = [{u, data (JSON text or nil), x, y, z, rz}]}],
  -- wrapped in an outer array; one transaction places every item (bags get their container, the trigger the
  -- world position), spends each zone's allowance and cools every point.
  DECLARE v_n INT DEFAULT 0;
  DECLARE v_first INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  INSERT INTO items (type_uname, hitpoints, data, x, y, z, rz, interior, dimension, loot_spawn_id, loot_zone, despawn_at)
    SELECT j.u, 5, j.data, j.x, j.y, j.z, j.rz, s.interior, s.dimension, s.id, s.zone, NOW() + INTERVAL p_despawn_minutes MINUTE
    FROM JSON_TABLE(p_rolls, '$[0][*]' COLUMNS (sid INT PATH '$.s', NESTED PATH '$.items[*]' COLUMNS (
      u VARCHAR(32) PATH '$.u', data LONGTEXT PATH '$.data', x FLOAT PATH '$.x', y FLOAT PATH '$.y', z FLOAT PATH '$.z',
      rz FLOAT PATH '$.rz'))) j
    JOIN loot_spawns s ON s.id = j.sid
    JOIN item_types t ON t.uname = j.u;
  SET v_n = ROW_COUNT();
  SET v_first = LAST_INSERT_ID();
  -- only the rows this call inserted get a container: ids never go below the first one the insert was handed
  INSERT INTO containers (kind, size, owner_item_id)
    SELECT t.category, IFNULL(t.container_size, 8), i.id
    FROM JSON_TABLE(p_rolls, '$[0][*]' COLUMNS (sid INT PATH '$.s')) j
    JOIN items i ON i.loot_spawn_id = j.sid AND i.id >= v_first
    JOIN item_types t ON t.uname = i.type_uname
    WHERE v_n > 0 AND t.category IN ('bag', 'safebox')
      AND NOT EXISTS (SELECT 1 FROM containers c WHERE c.owner_item_id = i.id);
  UPDATE world_budget b
    JOIN (SELECT s.zone, COUNT(*) AS n
          FROM JSON_TABLE(p_rolls, '$[0][*]' COLUMNS (sid INT PATH '$.s', NESTED PATH '$.items[*]' COLUMNS (
            u VARCHAR(32) PATH '$.u'))) j
          JOIN loot_spawns s ON s.id = j.sid JOIN item_types t ON t.uname = j.u GROUP BY s.zone) z ON z.zone = b.zone
    SET b.allowance = GREATEST(b.allowance - z.n, 0)
    WHERE b.category = 'loot';
  UPDATE loot_spawn_state st
    JOIN JSON_TABLE(p_rolls, '$[0][*]' COLUMNS (sid INT PATH '$.s', cd INT PATH '$.cd')) j ON j.sid = st.spawn_id
    SET st.next_roll_at = NOW() + INTERVAL j.cd SECOND;
  COMMIT;
  SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('created', CAST(v_n AS SIGNED)) AS payload;
END//

CREATE OR REPLACE PROCEDURE `staff_ban`(IN p_name VARCHAR(24), IN p_account_id INT, IN p_ip VARCHAR(45), IN p_serial CHAR(32),
                                      IN p_reason VARCHAR(128), IN p_by_account_id INT, IN p_by_name VARCHAR(24), IN p_seconds INT)
BEGIN
  DECLARE v_id INT DEFAULT 0;
  DECLARE v_expires DATETIME DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  IF EXISTS (SELECT 1 FROM bans WHERE name = p_name AND active = 1 AND (expires_at IS NULL OR expires_at > NOW()) FOR UPDATE) THEN
    ROLLBACK;
    SELECT 0 AS ok, 'ALREADY_BANNED' AS code, NULL AS payload;
  ELSE
    IF p_seconds > 0 THEN
      SET v_expires = NOW() + INTERVAL p_seconds SECOND;
    END IF;
    INSERT INTO bans (account_id, name, ip, serial, reason, by_account_id, by_name, expires_at)
      VALUES (p_account_id, p_name, p_ip, p_serial, p_reason, p_by_account_id, p_by_name, v_expires);
    SET v_id = LAST_INSERT_ID();
    INSERT INTO staff_actions (actor_account_id, actor_name, action, target_name, target_account_id, details)
      VALUES (p_by_account_id, p_by_name, 'ban', p_name, p_account_id,
              CONCAT(p_reason, ' (', IF(v_expires IS NULL, 'forever', CONCAT('until ', DATE_FORMAT(v_expires, '%Y-%m-%d %H:%i'))), ')'));
    COMMIT;
    SELECT 1 AS ok, 'OK' AS code,
           JSON_OBJECT('ban_id', CAST(v_id AS SIGNED), 'expires_at', DATE_FORMAT(v_expires, '%Y-%m-%d %H:%i:%s')) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `staff_unban`(IN p_name VARCHAR(24), IN p_by_account_id INT, IN p_by_name VARCHAR(24))
BEGIN
  DECLARE v_n INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  UPDATE bans SET active = 0 WHERE name = p_name AND active = 1;
  SET v_n = ROW_COUNT();
  IF v_n = 0 THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NOT_BANNED' AS code, NULL AS payload;
  ELSE
    INSERT INTO staff_actions (actor_account_id, actor_name, action, target_name, details)
      VALUES (p_by_account_id, p_by_name, 'unban', p_name, CONCAT(v_n, ' ban(s) lifted'));
    COMMIT;
    SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('lifted', CAST(v_n AS SIGNED)) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `staff_warn`(IN p_account_id INT, IN p_name VARCHAR(24), IN p_ip VARCHAR(45), IN p_serial CHAR(32),
                                       IN p_by_account_id INT, IN p_by_name VARCHAR(24), IN p_reason VARCHAR(128),
                                       IN p_max INT, IN p_ban_seconds INT)
BEGIN
  DECLARE v_warnings INT DEFAULT NULL;
  DECLARE v_ban_id INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  SELECT warnings INTO v_warnings FROM accounts WHERE id = p_account_id FOR UPDATE;
  IF v_warnings IS NULL THEN
    ROLLBACK;
    SELECT 0 AS ok, 'NO_ACCOUNT' AS code, NULL AS payload;
  ELSE
    SET v_warnings = v_warnings + 1;
    INSERT INTO staff_actions (actor_account_id, actor_name, action, target_name, target_account_id, details)
      VALUES (p_by_account_id, p_by_name, 'warn', p_name, p_account_id, CONCAT(v_warnings, '/', p_max, ': ', p_reason));
    IF v_warnings >= p_max THEN
      -- upstream level1.pwn: the fifth warning is a one-day ban; the counter starts again afterwards
      INSERT INTO bans (account_id, name, ip, serial, reason, by_account_id, by_name, expires_at)
        VALUES (p_account_id, p_name, p_ip, p_serial, CONCAT('Getting ', p_max, ' warnings'), p_by_account_id, p_by_name,
                IF(p_ban_seconds > 0, NOW() + INTERVAL p_ban_seconds SECOND, NULL));
      SET v_ban_id = LAST_INSERT_ID();
      INSERT INTO staff_actions (actor_account_id, actor_name, action, target_name, target_account_id, details)
        VALUES (p_by_account_id, p_by_name, 'ban', p_name, p_account_id, CONCAT('Getting ', p_max, ' warnings'));
      UPDATE accounts SET warnings = 0 WHERE id = p_account_id;
    ELSE
      UPDATE accounts SET warnings = v_warnings WHERE id = p_account_id;
    END IF;
    COMMIT;
    SELECT 1 AS ok, 'OK' AS code,
           JSON_OBJECT('warnings', CAST(v_warnings AS SIGNED), 'banned', CAST(v_ban_id > 0 AS SIGNED),
                       'ban_id', CAST(v_ban_id AS SIGNED)) AS payload;
  END IF;
END//

CREATE OR REPLACE PROCEDURE `vehicle_flush`(IN p_rows JSON)
BEGIN
  DECLARE v_n INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
  START TRANSACTION;
  UPDATE vehicles v
    JOIN JSON_TABLE(p_rows, '$[0][*]' COLUMNS (
      id INT PATH '$.id', x FLOAT PATH '$.x', y FLOAT PATH '$.y', z FLOAT PATH '$.z', rz FLOAT PATH '$.rz',
      health FLOAT PATH '$.health', fuel FLOAT PATH '$.fuel', locked TINYINT PATH '$.locked')) j ON j.id = v.id
    SET v.x = j.x, v.y = j.y, v.z = j.z, v.rz = j.rz, v.health = j.health, v.fuel = j.fuel, v.locked = j.locked;
  SET v_n = ROW_COUNT();
  COMMIT;
  SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT('updated', CAST(v_n AS SIGNED)) AS payload;
END//

CREATE OR REPLACE PROCEDURE `weapon_unload`(
  IN p_char_id INT, IN p_weapon_id INT, IN p_weapon_data JSON,
  IN p_ammo_uname VARCHAR(32), IN p_ammo_data JSON,
  IN p_x FLOAT, IN p_y FLOAT, IN p_z FLOAT, IN p_rz FLOAT,
  IN p_interior TINYINT, IN p_dimension INT)
BEGIN
  DECLARE v_held_ok INT DEFAULT 0;
  DECLARE v_cat VARCHAR(16) DEFAULT NULL;
  DECLARE v_ammo_id INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  SELECT category INTO v_cat FROM item_types WHERE uname = p_ammo_uname;
  IF v_cat IS NULL THEN
    SELECT 0 AS ok, 'UNKNOWN_TYPE' AS code, NULL AS payload;
  ELSE
    SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
    START TRANSACTION;
    SELECT COUNT(*) INTO v_held_ok FROM items
      WHERE id = p_weapon_id AND holder_char_id = p_char_id AND holder_kind = 'held' FOR UPDATE;
    IF v_held_ok = 0 THEN
      ROLLBACK;
      SELECT 0 AS ok, 'NOT_HELD' AS code, NULL AS payload;
    ELSE
      UPDATE items SET data = p_weapon_data WHERE id = p_weapon_id;
      INSERT INTO items (type_uname, hitpoints, data, x, y, z, rz, interior, dimension)
        VALUES (p_ammo_uname, 5, p_ammo_data, p_x, p_y, p_z, p_rz, p_interior, p_dimension);
      SET v_ammo_id = LAST_INSERT_ID();
      COMMIT;
      SELECT 1 AS ok, 'OK' AS code, JSON_OBJECT(
        'weapon_id', CAST(p_weapon_id AS SIGNED),
        'ammo_item_id', CAST(v_ammo_id AS SIGNED)
      ) AS payload;
    END IF;
  END IF;
END//

CREATE OR REPLACE TRIGGER items_ground_reset BEFORE UPDATE ON items FOR EACH ROW
BEGIN
  IF NOT (OLD.x <=> NEW.x AND OLD.y <=> NEW.y AND OLD.z <=> NEW.z)
    AND OLD.ground_nx <=> NEW.ground_nx AND OLD.ground_ny <=> NEW.ground_ny THEN
    SET NEW.ground_nx = NULL, NEW.ground_ny = NULL;
  END IF;
END//

CREATE OR REPLACE TRIGGER items_world_pos_insert AFTER INSERT ON items FOR EACH ROW
BEGIN
  IF NEW.x IS NOT NULL THEN
    INSERT INTO world_items_pos (item_id, pos) VALUES (NEW.id, POINT(NEW.x, NEW.y));
  END IF;
END//

CREATE OR REPLACE TRIGGER items_world_pos_update AFTER UPDATE ON items FOR EACH ROW
BEGIN
  IF NEW.x IS NULL THEN
    IF OLD.x IS NOT NULL THEN
      DELETE FROM world_items_pos WHERE item_id = NEW.id;
    END IF;
  ELSEIF NOT (OLD.x <=> NEW.x AND OLD.y <=> NEW.y) THEN
    INSERT INTO world_items_pos (item_id, pos) VALUES (NEW.id, POINT(NEW.x, NEW.y))
      ON DUPLICATE KEY UPDATE pos = VALUE(pos);
  END IF;
END//

CREATE OR REPLACE EVENT `ev_despawn_items` ON SCHEDULE EVERY 1 MINUTE STARTS '2026-10-25 12:32:28' ON COMPLETION NOT PRESERVE ENABLE DO DELETE FROM items WHERE despawn_at IS NOT NULL AND despawn_at < NOW() AND x IS NOT NULL//

CREATE OR REPLACE EVENT `ev_expire_bans` ON SCHEDULE EVERY 1 MINUTE STARTS '2026-10-25 12:32:28' ON COMPLETION NOT PRESERVE ENABLE DO UPDATE bans SET active = 0 WHERE active = 1 AND expires_at IS NOT NULL AND expires_at < NOW()//

CREATE OR REPLACE EVENT `ev_item_history` ON SCHEDULE EVERY 1 HOUR STARTS '2026-10-25 12:32:28' ON COMPLETION NOT PRESERVE ENABLE DO DELETE HISTORY FROM items BEFORE SYSTEM_TIME NOW() - INTERVAL 7 DAY//

DELIMITER ;
